"""The figures and tables are generated by a script from logged results."""
import subprocess
import sys
from pathlib import Path

import pytest

from conveyor_sort.metrics import ExperimentConfig, append_csv, run_experiment
from conveyor_sort.prediction.benchmark import prediction_errors

EVALUATION = Path(__file__).resolve().parents[1] / "evaluation"


def run(script: str, *args) -> str:
    result = subprocess.run([sys.executable, str(EVALUATION / script), *map(str, args)], capture_output=True, text=True, timeout=600)
    assert result.returncode == 0, result.stderr[-2000:]
    return result.stdout


def test_figures_and_tables_from_logged_results(tmp_path):
    pytest.importorskip("matplotlib")
    results, out = tmp_path / "results", tmp_path / "figures"
    for mode in ("single", "fixed", "coordinated"):                         # a small manipulation log
        append_csv(results / "manipulation.csv", run_experiment(ExperimentConfig(mode, 0.1, 0.6, 4, seed=0, mode=mode)))
    run("benchmark_prediction.py", "--csv", results / "prediction.csv", "--trials", 5)
    assert prediction_errors("cv", 0.0, [1.0], trials=2).max() < 1e-6

    stdout = run("make_figures.py", "--results", results, "--out", out)
    assert (out / "manipulation_sorted.png").stat().st_size > 10_000
    assert (out / "prediction_error.png").stat().st_size > 10_000
    assert "perception.csv not found" in stdout and not (out / "perception.png").exists()      # missing logs are skipped
    tables = (out / "tables.md").read_text()
    assert "| all streams |" in tables and "| sorted correctly |" in tables and "Prediction: mean position error" in tables
    assert "Perception" not in tables and "Command mode" not in tables


def test_physical_prediction_table(tmp_path):
    pytest.importorskip("matplotlib")
    results, out = tmp_path / "results", tmp_path / "figures"
    results.mkdir()
    rows = ["detector,predictor,horizon_s,predictions,mean_error_mm,p95_error_mm,step_mean_s,step_max_s,speed,hyper_speed"]
    rows += [f"{d},{p},{h},100,{h * 2},{h * 3},0.2,0.4,0.1,1.0" for d in ("gt", "hsv") for p in ("cv", "kalman") for h in (0.5, 3.0)]
    (results / "prediction_physics.csv").write_text("\n".join(rows) + "\n")
    run("make_figures.py", "--results", results, "--out", out)
    tables = (out / "tables.md").read_text()
    assert "Prediction on the physical belt (0.1 m/s)" in tables
    assert "| hsv | 0.200 / 0.400 | 1.00 / 1.00 | 6.00 / 6.00 |" in tables


def test_committed_figures_exist():
    for name in ("manipulation_sorted.png", "perception.png", "prediction_error.png", "tables.md"):
        assert (EVALUATION / "figures" / name).exists(), name
